const button=document.getElementById("enable-notifications");const test=document.getElementById("test-alert");const say=text=>document.getElementById("admin-feedback").textContent=text;let registration,subscription;async function call(path,data){const response=await fetch("/api/admin/"+path,{method:data?"POST":"GET",headers:data?{"Content-Type":"application/json"}:{},body:data?JSON.stringify(data):void 0});const result=await response.json();if(!response.ok)throw new Error(result.error||"N\xE3o foi poss\xEDvel ativar os avisos.");return result}async function worker(){if(!("serviceWorker"in navigator)||!("PushManager"in window)||!("Notification"in window))throw new Error("Este navegador n\xE3o suporta avisos push. No iPhone, instale o painel na tela inicial.");registration=await navigator.serviceWorker.register("/panel-worker.js",{scope:"/"});await navigator.serviceWorker.ready;return registration}button.addEventListener("click",async()=>{button.disabled=true;try{if(!("Notification"in window))throw new Error("Abra o painel no Chrome do celular para ativar os avisos.");const permission=await Promise.race([Notification.requestPermission(),new Promise((_,reject)=>setTimeout(()=>reject(new Error("A permiss\xE3o n\xE3o foi conclu\xEDda. Abra no navegador do celular e permita notifica\xE7\xF5es.")),12e3))]);if(permission!=="granted")throw new Error("Notifica\xE7\xF5es bloqueadas. Libere nas configura\xE7\xF5es do navegador.");await worker();const{publicKey}=await call("push-key");const key=Uint8Array.from(atob(publicKey.replace(/-/g,"+").replace(/_/g,"/")),c=>c.charCodeAt(0));subscription=await registration.pushManager.getSubscription()||await registration.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:key});await call("push-subscribe",subscription.toJSON());button.textContent="Notifica\xE7\xF5es ativadas \u2713";say("Avisos ativados neste aparelho. Use Testar aviso para conferir.")}catch(error){say(error.message)}finally{button.disabled=false}});test.addEventListener("click",async()=>{
 if(test.disabled)return;
 document.getElementById("enable-sound").click();
 test.disabled=true;
 try{
  await worker();subscription=await registration.pushManager.getSubscription();
  if(!subscription||Notification.permission!=="granted"){say("Ative as notificações primeiro para testar o aviso neste aparelho.");return;}
  say("O aviso será enviado em 5 segundos. Pode minimizar o navegador para conferir.");
  const deadline=Date.now()+5000;
  while(Date.now()<deadline){test.textContent=`Testar aviso · ${Math.ceil((deadline-Date.now())/1000)}s`;await new Promise(resolve=>setTimeout(resolve,Math.min(250,deadline-Date.now())));}
  test.textContent="Enviando…";
  const result=await call("push-test",{endpoint:subscription.endpoint});
  say(result.sent?"Aviso de teste enviado. Confira as notificações do PC ou celular.":"O serviço não entregou o teste. Ative as notificações novamente.");
 }catch(error){say(error.message);}
 finally{test.disabled=false;test.textContent="Testar aviso";}
});export async function stopPush(){try{const r=await navigator.serviceWorker.getRegistration();const sub=await r?.pushManager.getSubscription();if(sub){await call("push-unsubscribe",{endpoint:sub.endpoint});await sub.unsubscribe()}}catch{}}
